// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address newOwner) public {

        if (caller == address(0)) caller = address(1);

        vm.prank(address(0));
        c.transferOwnership(caller);

        vm.prank(caller);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.owner() == newOwner);
    }
}
